def greedy(w,k=8):
    F=lib(w); keys=list(F.keys())
    sel=[]; 
    for step in range(k):
        bestk=None;bestr=1e9
        for kk in keys:
            if kk in sel: continue
            X=np.column_stack([F[s] for s in sel+[kk]])
            c,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None)
            rr=np.mean((X@c-dv_dt)**2)/np.var(dv_dt)
